SELECT COUNT(*)
FROM security_event
WHERE event_kind = #{eventKind}
  AND created_at >= #{since}

SELECT COUNT(*)
FROM security_event
WHERE event_kind = #{eventKind}
  AND platform = #{platform}
  AND bot_id = #{botId}
  AND group_id = #{groupId}
  AND created_at >= #{since}

SELECT COUNT(*)
FROM security_event
WHERE created_at >= #{since}

SELECT COUNT(*)
FROM security_event
WHERE created_at >= #{from}
  AND created_at < #{to}

SELECT id, event_kind AS eventKind, platform, bot_id AS botId, group_id AS groupId,
user_id AS userId, detail, trace_id AS traceId, created_at AS createdAt
FROM security_event

    AND event_kind = #{eventKind}
    AND platform = #{platform}
    AND bot_id = #{botId}
    AND group_id = #{groupId}
    AND trace_id = #{traceId}
    AND detail LIKE CONCAT('%', #{keyword}, '%')
    AND created_at >= #{from}
    AND created_at < #{to}

ORDER BY created_at DESC, id DESC
LIMIT #{limit} OFFSET #{offset}

